// План: specs/proxy-access.md, тест 1.4 (#5068e1). Несколько ролей: владелец 050-0000017 (owner17) и доверенный 050-0000005 (provider).
// Только чтение: ничего не переключаем, не создаём, деньги не затрагиваем -> @prod-safe.
// ВНИМАНИЕ: селекторы по тексту из брифа (research/5068e1.md), в живом браузере не проверялись (тесты только записываются, запуск — /qa-regress).
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';

const RIGHTS = ['אישור עסקאות', 'שחרור כסף מהנאמנות', 'מחלוקות ובוררות'];

async function openFromProfile(page: Page, menuItem: string) {
  await page.goto('/profile');
  await page.getByText(menuItem, { exact: true }).first().click();
}

/** Права, включённые у владельца: переключатель — role=switch/checkbox рядом с названием права. */
async function enabledRights(page: Page): Promise<string[]> {
  const enabled: string[] = [];
  for (const right of RIGHTS) {
    const label = page.getByText(right, { exact: true }).first();
    await expect(label).toBeVisible();
    const toggle = label.locator('xpath=ancestor-or-self::*[.//*[@role="switch" or @role="checkbox"] or @role="switch" or @role="checkbox"][1]').getByRole('switch').or(
      label.locator('xpath=ancestor-or-self::*[.//*[@role="switch" or @role="checkbox"]][1]').getByRole('checkbox'),
    ).first();
    const state = (await toggle.getAttribute('aria-checked')) ?? ((await toggle.isChecked().catch(() => false)) ? 'true' : 'false');
    if (state === 'true') enabled.push(right);
  }
  return enabled;
}

test('מיופה כוח: הקישור וההרשאות מופיעים בשני הצדדים @iphone @prod-safe (#5068e1)', async ({ asUser }) => {
  const owner = await asUser('owner17');
  const trustee = await asUser('provider');

  // владелец: «מקושר לחשבון SafePay», без «טרם אישר את ההזמנה»
  await openFromProfile(owner, 'גיבוי ומיופה כוח');
  await expect(owner.getByText('מקושר לחשבון SafePay').first()).toBeVisible();
  await expect(owner.getByText('טרם אישר את ההזמנה')).toHaveCount(0);
  const enabled = await enabledRights(owner);

  // доверенный: аккаунт владельца в списке, без ошибки загрузки
  await openFromProfile(trustee, 'מיופה כוח של חשבון אחר');
  await expect(trustee.getByText('QA פרופיל 17').first()).toBeVisible();
  await expect(trustee.getByText('לא הצלחנו לטעון את החשבונות')).toHaveCount(0);

  // каждое включённое у владельца право названо у доверенного
  for (const right of enabled) {
    await expect(trustee.getByText(right, { exact: true }).first(), `право «${right}» у доверенного`).toBeVisible();
  }
});
